using System.Reflection;
using Xbc.DbAccess.Entity;

namespace Xbc.DbAccess.IntegrationTests.Infrastructure
{
    /// <summary>
    /// 测试实体到建表 DDL 的生成器（覆盖 PostgreSQL、SQL Server、MySQL、Oracle 与 SQLite 五方言的测试所需类型集）：
    /// 反射公开映射特性（[Table]/[PrimaryKey]/[Column]/[NotMapped]），映射规则与框架一致（公共读写属性默认映射）。
    /// <para>类型映射与方言原生 bulk 插入器的写入映射对齐：DateTime 映射为不带时区的 timestamp（Pg）、
    /// DateTimeOffset 映射为带时区的 timestamptz（Pg）；自增列 Pg/Oracle 用 GENERATED BY DEFAULT（允许 Upsert 显式值路径）。</para>
    /// <para>Oracle 23c 之前不支持 DROP TABLE IF EXISTS，DROP 语句以 PL/SQL 匿名块吞掉"表不存在"异常（ORA-00942）实现幂等。</para>
    /// <para>SQLite 要求 AUTOINCREMENT 紧随 INTEGER PRIMARY KEY 之后，自增主键约束生成为 PRIMARY KEY AUTOINCREMENT；
    /// 其余类型依托动态类型亲和性（integer/real/text/blob）存储。</para>
    /// </summary>
    internal static class DdlGenerator
    {
        /// <summary>
        /// 生成实体的建表 DDL（先 DROP 再 CREATE，测试基类按此顺序执行）。
        /// </summary>
        /// <param name="dialect">目标方言。</param>
        /// <param name="entityType">实体类型。</param>
        /// <returns>dropSql 与 createSql。</returns>
        public static (string DropSql, string CreateSql) Generate(RealDbDialect dialect, Type entityType)
        {
            var tableAttribute = entityType.GetCustomAttribute<TableAttribute>()
                ?? throw new ArgumentException($"实体类型 '{entityType.Name}' 缺少 [Table] 特性，无法生成建表 DDL。", nameof(entityType));

            var openQuote = dialect switch { RealDbDialect.MySql => "`", RealDbDialect.SqlServer => "[", _ => "\"" };
            var closeQuote = dialect switch { RealDbDialect.MySql => "`", RealDbDialect.SqlServer => "]", _ => "\"" };
            string Quote(string identifier) => openQuote + identifier + closeQuote;

            var tableName = tableAttribute.Name;

            var columnDefinitions = new List<string>();
            string? primaryKeyColumn = null;
            var mySqlIdentityKeys = new List<string>();// MySQL 非主键 AUTO_INCREMENT 列须建索引（引擎要求 auto 列必须是键）

            foreach (var property in entityType.GetProperties(BindingFlags.Public | BindingFlags.Instance))
            {
                if (!property.CanRead || !property.CanWrite)
                    continue;
                if (property.GetCustomAttribute<NotMappedAttribute>() != null || property.GetCustomAttribute<NavigationAttribute>() != null)
                    continue;

                var primaryKeyAttribute = property.GetCustomAttribute<PrimaryKeyAttribute>();
                var columnAttribute = property.GetCustomAttribute<ColumnAttribute>();

                var columnName = columnAttribute?.Name ?? primaryKeyAttribute?.Name ?? property.Name;
                var isIdentity = primaryKeyAttribute?.IsIdentity ?? columnAttribute?.IsIdentity ?? false;
                var isPrimaryKey = primaryKeyAttribute != null;
                if (isPrimaryKey)
                    primaryKeyColumn = columnName;

                var effectiveType = Nullable.GetUnderlyingType(property.PropertyType) ?? property.PropertyType;
                var isNullable = Nullable.GetUnderlyingType(property.PropertyType) != null
                    || (!property.PropertyType.IsValueType && property.PropertyType != typeof(byte[]));

                string columnType;
                if (columnAttribute?.IsJson == true || columnAttribute?.EnumAsString == true)
                {
                    // JSON/枚举名称字符串列均按文本存储
                    columnType = dialect switch { RealDbDialect.PgSql => "text", RealDbDialect.MySql => "text", RealDbDialect.Oracle => "nclob", RealDbDialect.Sqlite => "text", _ => "nvarchar(max)" };
                }
                else if (effectiveType.IsEnum)
                {
                    columnType = MapColumnType(dialect, Enum.GetUnderlyingType(effectiveType));
                }
                else
                {
                    columnType = MapColumnType(dialect, effectiveType);
                }

                var identityClause = isIdentity
                    ? dialect switch
                    {
                        RealDbDialect.PgSql => " GENERATED BY DEFAULT AS IDENTITY",
                        RealDbDialect.Oracle => " GENERATED BY DEFAULT AS IDENTITY",
                        RealDbDialect.MySql => " AUTO_INCREMENT",
                        // SQLite 的 AUTOINCREMENT 并入主键约束（语法要求紧随 PRIMARY KEY 之后）
                        RealDbDialect.Sqlite => "",
                        _ => " IDENTITY(1,1)"
                    }
                    : string.Empty;

                // 主键列内联主键约束；自增列隐式非空
                var constraints = new List<string>();
                if (isPrimaryKey)
                    constraints.Add(isIdentity && dialect == RealDbDialect.Sqlite ? "PRIMARY KEY AUTOINCREMENT" : "PRIMARY KEY");
                else if (!isNullable && !isIdentity)
                    constraints.Add("NOT NULL");

                if (isIdentity && !isPrimaryKey && dialect == RealDbDialect.MySql)
                    mySqlIdentityKeys.Add(Quote(columnName));

                columnDefinitions.Add($"{Quote(columnName)} {columnType}{identityClause}{(constraints.Count > 0 ? " " + string.Join(" ", constraints) : string.Empty)}");
            }

            if (primaryKeyColumn == null)
                throw new ArgumentException($"实体类型 '{entityType.Name}' 缺少 [PrimaryKey] 特性，无法生成建表 DDL。", nameof(entityType));

            string dropSql;
            if (dialect == RealDbDialect.Oracle)
            {
                // Oracle 23c 前无 DROP TABLE IF EXISTS：匿名块吞"表不存在"（ORA-00942）实现幂等
                dropSql = $"BEGIN EXECUTE IMMEDIATE 'DROP TABLE {Quote(tableName)}'; EXCEPTION WHEN OTHERS THEN IF SQLCODE != -942 THEN RAISE; END IF; END;";
            }
            else
            {
                dropSql = $"DROP TABLE IF EXISTS {Quote(tableName)}";
            }

            // MySQL 非主键 AUTO_INCREMENT 列的表级 KEY 索引（引擎要求 auto 列必须是键，否则建表失败）
            var keyConstraints = mySqlIdentityKeys.Count > 0
                ? ", " + string.Join(", ", mySqlIdentityKeys.Select(name => $"KEY ({name})"))
                : string.Empty;
            var createSql = $"CREATE TABLE {Quote(tableName)} ({string.Join(", ", columnDefinitions)}{keyConstraints})";
            return (dropSql, createSql);
        }

        /// <summary>
        /// CLR 类型到列类型的映射（覆盖测试实体使用的类型集）。
        /// </summary>
        private static string MapColumnType(RealDbDialect dialect, Type type)
        {
            return dialect switch
            {
                RealDbDialect.PgSql => MapPgSql(type),
                RealDbDialect.SqlServer => MapSqlServer(type),
                RealDbDialect.MySql => MapMySql(type),
                RealDbDialect.Oracle => MapOracle(type),
                RealDbDialect.Sqlite => MapSqlite(type),
                _ => throw new NotSupportedException($"测试 DDL 生成器不支持方言 {dialect}。")
            };
        }

        private static string MapPgSql(Type type)
        {
            if (type == typeof(bool)) return "boolean";
            if (type == typeof(byte)) return "smallint";
            if (type == typeof(short)) return "smallint";
            if (type == typeof(int)) return "integer";
            if (type == typeof(long)) return "bigint";
            if (type == typeof(float)) return "real";
            if (type == typeof(double)) return "double precision";
            if (type == typeof(decimal)) return "numeric(18,4)";
            if (type == typeof(string)) return "text";
            if (type == typeof(DateTime)) return "timestamp";
            if (type == typeof(DateTimeOffset)) return "timestamptz";
            if (type == typeof(Guid)) return "uuid";
            if (type == typeof(byte[])) return "bytea";

            throw new NotSupportedException($"测试 DDL 生成器不支持 CLR 类型 '{type.Name}'（方言 PostgreSQL），请补充类型映射。");
        }

        private static string MapSqlServer(Type type)
        {
            if (type == typeof(bool)) return "bit";
            if (type == typeof(byte)) return "tinyint";
            if (type == typeof(short)) return "smallint";
            if (type == typeof(int)) return "int";
            if (type == typeof(long)) return "bigint";
            if (type == typeof(float)) return "real";
            if (type == typeof(double)) return "float";
            if (type == typeof(decimal)) return "decimal(18,4)";
            if (type == typeof(string)) return "nvarchar(400)";
            if (type == typeof(DateTime)) return "datetime2";
            if (type == typeof(DateTimeOffset)) return "datetimeoffset";
            if (type == typeof(Guid)) return "uniqueidentifier";
            if (type == typeof(byte[])) return "varbinary(max)";

            throw new NotSupportedException($"测试 DDL 生成器不支持 CLR 类型 '{type.Name}'（方言 SQL Server），请补充类型映射。");
        }

        private static string MapMySql(Type type)
        {
            if (type == typeof(bool)) return "tinyint(1)";
            if (type == typeof(byte)) return "tinyint unsigned";
            if (type == typeof(short)) return "smallint";
            if (type == typeof(int)) return "int";
            if (type == typeof(long)) return "bigint";
            if (type == typeof(float)) return "float";
            if (type == typeof(double)) return "double";
            if (type == typeof(decimal)) return "decimal(18,4)";
            if (type == typeof(string)) return "varchar(400)";
            if (type == typeof(DateTime)) return "datetime(6)";
            if (type == typeof(DateTimeOffset)) return "timestamp(6)";
            if (type == typeof(Guid)) return "char(36)";
            if (type == typeof(byte[])) return "longblob";

            throw new NotSupportedException($"测试 DDL 生成器不支持 CLR 类型 '{type.Name}'（方言 MySQL），请补充类型映射。");
        }

        private static string MapOracle(Type type)
        {
            if (type == typeof(bool)) return "number(1)";
            if (type == typeof(byte)) return "number(3)";
            if (type == typeof(short)) return "number(5)";
            if (type == typeof(int)) return "number(10)";
            if (type == typeof(long)) return "number(19)";
            if (type == typeof(float)) return "binary_float";
            if (type == typeof(double)) return "binary_double";
            if (type == typeof(decimal)) return "number(18,4)";
            if (type == typeof(string)) return "nvarchar2(400)";
            if (type == typeof(DateTime)) return "timestamp";
            if (type == typeof(DateTimeOffset)) return "timestamp with time zone";
            if (type == typeof(Guid)) return "raw(16)";
            if (type == typeof(byte[])) return "blob";

            throw new NotSupportedException($"测试 DDL 生成器不支持 CLR 类型 '{type.Name}'（方言 Oracle），请补充类型映射。");
        }

        private static string MapSqlite(Type type)
        {
            // SQLite 动态类型：整数系用 integer、浮点系用 real、文本系用 text、二进制用 blob（数值精度依托存储类保留）
            if (type == typeof(bool)) return "integer";
            if (type == typeof(byte)) return "integer";
            if (type == typeof(short)) return "integer";
            if (type == typeof(int)) return "integer";
            if (type == typeof(long)) return "integer";
            if (type == typeof(float)) return "real";
            if (type == typeof(double)) return "real";
            if (type == typeof(decimal)) return "numeric(18,4)";
            if (type == typeof(string)) return "text";
            if (type == typeof(DateTime)) return "text";
            if (type == typeof(DateTimeOffset)) return "text";
            if (type == typeof(Guid)) return "text";
            if (type == typeof(byte[])) return "blob";

            throw new NotSupportedException($"测试 DDL 生成器不支持 CLR 类型 '{type.Name}'（方言 SQLite），请补充类型映射。");
        }
    }
}
